def build_image(prefixes, rng, shuffle_ni=True, direct_children=True):
    """prefixes: list of (len, value128, hop)"""
    f0 = [p for p in prefixes if p[0] <= 16]
    g16 = {}
    g64 = {}
    for (ln, hop, v) in prefixes:
        if 17 <= ln <= 64: g16.setdefault(v >> 112, []).append((ln, hop, v))
        elif ln >= 65: g64.setdefault(v >> 64, []).append((ln, hop, v))
    roots = []
    if f0: roots.append(('root', build_node(0, 0, 0, f0)))
    for k in sorted(g16): roots.append(('f16', k, build_node(16, 16, k << 112, g16[k])))
    for k in sorted(g64): roots.append(('f64', k, build_node(64, 64, k, g64[k])))
    nodes = []
    for r in roots:
        collect(r[1] if r[0] == 'root' else r[2], nodes)
    # bulk / direct split and spans (must precede stage assignment)
    for n in nodes:
        n.span = 2 if n.type in (2, 3, 5) else 1
        n.direct = []
        n.bulk_keys = []
        if n.type == 3:
            keys = [k for (k, _) in n.children]
            if direct_children:
                k = rng.randint(0, min(3, len(keys) - 4))
                n.direct = sorted(rng.sample(keys, k))
            n.bulk_keys = [k for k in keys if k not in n.direct]
            for (k, c) in n.children:
                if k in n.bulk_keys:
                    c.bulk_root = True
                    c.span = 2
    for r in roots:
        assign_stages(r[1] if r[0] == 'root' else r[2], 11, rng)
    for n in nodes:
        for (k, c) in n.children:
            if c.stage >= n.stage:
                raise SystemExit('stage bug: parent t%d st%d child t%d st%d h%d bulkroot=%s pbulk=%d pk=%s'
                                 % (n.type, n.stage, c.type, c.stage, height(c), c.bulk_root,
                                    len(n.bulk_keys), n.direct))
    # placement
    cells = [0] * 11
    by_stage = {s: [n for n in nodes if n.stage == s] for s in range(11)}
    for s in range(11):
        cur = 0
        parents = [n for n in nodes if n.type == 3 and n.bulk_keys
                   and n.bulk_stage == s]
        rng.shuffle(parents)
        for p in parents:
            p.bulk_base = cur
            order = sorted(p.bulk_keys)
            for i, k in enumerate(order):
                child = [c for (kk, c) in p.children if kk == k][0]
                child.cell = cur + 2 * i
            cur += 2 * len(order)
        rest2 = [n for n in by_stage[s] if not n.bulk_root and n.span == 2]
        rest1 = [n for n in by_stage[s] if not n.bulk_root and n.span == 1]
        rng.shuffle(rest2); rng.shuffle(rest1)
        lead = 2 * rng.randint(0, len(rest1) // 2) if rest1 else 0
        for n in rest1[:lead]:
            n.cell = cur; cur += 1
        for n in rest2:
            n.cell = cur; cur += 2
        for n in rest1[lead:]:
            n.cell = cur; cur += 1
        cells[s] = cur
    # NI dictionary / vector
    def pattern_of(n):
        p = 0
        for (ln, hop, v) in n.locals:
            l = ln - n.depth
            val = (v >> (128 - n.depth - l)) & ((1 << l) - 1) if l else 0
            p |= 1 << ((1 << l) + val)
        return p
    pats = sorted({pattern_of(n) for n in nodes if n.type <= 3})
    order = [n for n in nodes if n.type <= 3]
    if shuffle_ni: rng.shuffle(order)
    nis = []
    for n in order:
        pat = pattern_of(n)
        n.bitmap_id = pats.index(pat)
        n.ni_base = len(nis) if pat else 0
